-- The tenant onboarding run and its transitions (Wave 6 PR10; SPINE-CONTRACT 1.8, item 10).
--
-- The name sorts after 20261010235900_tenant_rls, so the tenant tables created here
-- are policed by this file itself (rlsMigrationOrder.test.ts checks that).
-- The CREATE TABLE and index statements are generated by `prisma migrate diff`;
-- everything below the line of hand-written SQL is an invariant Prisma cannot
-- express, and each one must hold for every writer, not only for the domain.
--
-- The state moves out of Tenant.config.onboarding (JSON) and into this table. The
-- JSON column is not dropped here: nothing writes it any more, and the backfill
-- below reads it once. Dropping it is a later migration, after the run has been
-- live long enough to be the only reader.

-- CreateTable
CREATE TABLE "tenant_onboarding_runs" (
    "id" TEXT NOT NULL,
    "tenantId" TEXT NOT NULL,
    "state" TEXT NOT NULL DEFAULT 'draft',
    "revision" INTEGER NOT NULL DEFAULT 0,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "tenant_onboarding_runs_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "onboarding_transitions" (
    "id" TEXT NOT NULL,
    "tenantId" TEXT NOT NULL,
    "runId" TEXT NOT NULL,
    "event" TEXT NOT NULL,
    "fromState" TEXT NOT NULL,
    "toState" TEXT NOT NULL,
    "revision" INTEGER NOT NULL,
    "actorPartyId" TEXT,
    "reason" TEXT,
    "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "onboarding_transitions_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "tenant_onboarding_runs_tenantId_key" ON "tenant_onboarding_runs"("tenantId");

-- CreateIndex
CREATE UNIQUE INDEX "tenant_onboarding_runs_tenantId_id_key" ON "tenant_onboarding_runs"("tenantId", "id");

-- CreateIndex
CREATE INDEX "onboarding_transitions_tenantId_runId_revision_idx" ON "onboarding_transitions"("tenantId", "runId", "revision");

-- AddForeignKey
ALTER TABLE "onboarding_transitions" ADD CONSTRAINT "onboarding_transitions_tenantId_runId_fkey" FOREIGN KEY ("tenantId", "runId") REFERENCES "tenant_onboarding_runs"("tenantId", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- ---------------------------------------------------------------------------
-- Hand-written from here down.
-- ---------------------------------------------------------------------------

-- 1. The state list is closed. A new state is a migration, because the transition
--    table TENANT_ONBOARDING_TRANSITIONS in @kaizen/shared and this list change together.
ALTER TABLE "tenant_onboarding_runs"
  ADD CONSTRAINT "tenant_onboarding_runs_state_known"
  CHECK ("state" IN ('draft', 'company_profile', 'statutory_configured', 'openings_imported', 'verified', 'active', 'blocked'));

ALTER TABLE "tenant_onboarding_runs"
  ADD CONSTRAINT "tenant_onboarding_runs_revision_non_negative"
  CHECK ("revision" >= 0);

ALTER TABLE "onboarding_transitions"
  ADD CONSTRAINT "onboarding_transitions_from_state_known"
  CHECK ("fromState" IN ('draft', 'company_profile', 'statutory_configured', 'openings_imported', 'verified', 'active', 'blocked'));

ALTER TABLE "onboarding_transitions"
  ADD CONSTRAINT "onboarding_transitions_to_state_known"
  CHECK ("toState" IN ('draft', 'company_profile', 'statutory_configured', 'openings_imported', 'verified', 'active', 'blocked'));

-- 2. The history is append-only. The command writes one row per change and nothing
--    updates or deletes one, so the trigger refuses both for every role, the table
--    owner included. A correction is a new row.
CREATE OR REPLACE FUNCTION "onboarding_transitions_immutable"()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'onboarding transitions are immutable; a correction is a new transition'
    USING ERRCODE = 'check_violation';
END
$$;

CREATE TRIGGER "onboarding_transitions_immutable"
  BEFORE UPDATE OR DELETE ON "onboarding_transitions"
  FOR EACH ROW EXECUTE FUNCTION "onboarding_transitions_immutable"();

-- 3. Row-level security on the new tables. Written out, not looped, so that the
--    migration is correct on its own and rlsMigrationOrder.test.ts can read it.
ALTER TABLE "tenant_onboarding_runs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "tenant_onboarding_runs" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "tenant_isolation" ON "tenant_onboarding_runs";
CREATE POLICY "tenant_isolation" ON "tenant_onboarding_runs"
  USING ("tenantId" = current_setting('app.tenant_id', true))
  WITH CHECK ("tenantId" = current_setting('app.tenant_id', true));

ALTER TABLE "onboarding_transitions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "onboarding_transitions" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "tenant_isolation" ON "onboarding_transitions";
CREATE POLICY "tenant_isolation" ON "onboarding_transitions"
  USING ("tenantId" = current_setting('app.tenant_id', true))
  WITH CHECK ("tenantId" = current_setting('app.tenant_id', true));

-- 4. The application role. The run is advanced, so it may read, insert and update it.
--    The history is only ever inserted and read: DELETE is revoked outright, and
--    UPDATE is refused by the trigger above for every role, so no grant can widen it.
--    Guarded, as in 20261013100000_commitment_record: on a fresh database the role is
--    created by tenant_rls, which grants on every table anyway.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'kaizen_app') THEN
    GRANT SELECT, INSERT, UPDATE ON "tenant_onboarding_runs" TO "kaizen_app";
    GRANT SELECT, INSERT ON "onboarding_transitions" TO "kaizen_app";
    REVOKE UPDATE, DELETE ON "onboarding_transitions" FROM "kaizen_app";
  END IF;
END
$$;

-- 5. Backfill: one run per tenant, from the JSON status it carried. A status that is
--    not one of the seven states, or no status at all, is a draft, which is what the
--    old code reported for such a tenant. Re-runnable: a tenant that already has a run
--    is left alone. No transition rows are written, because the old code kept no history.
-- BACKFILL-BEGIN
INSERT INTO "tenant_onboarding_runs" ("id", "tenantId", "state", "revision", "createdAt", "updatedAt")
SELECT
  gen_random_uuid()::text,
  t."id",
  CASE
    WHEN t."config" -> 'onboarding' ->> 'status' IN ('draft', 'company_profile', 'statutory_configured', 'openings_imported', 'verified', 'active', 'blocked')
      THEN t."config" -> 'onboarding' ->> 'status'
    ELSE 'draft'
  END,
  0,
  now(),
  now()
FROM "tenants" t
WHERE NOT EXISTS (SELECT 1 FROM "tenant_onboarding_runs" r WHERE r."tenantId" = t."id");
-- BACKFILL-END
